-- Migration 0057_email_intake: generated by drizzle-kit (tables, keys, indexes), RLS, the resolve function and the legacy-token cleanup hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #529)
-- Email forward-in intake (#54 part 2):
--   * intake_address, intake_allowlist and intake_message: tenant tables (tenantTable()) under
--     FORCE RLS with ws_isolation (tenantPolicy()). A retired (local_part, domain) stays in the
--     table and is unique across all rows, so an address is never handed out twice.
--   * app_resolve_intake_address(local_part, domain): the one workspace-free lookup, for inbound
--     mail whose sender is not a member. SECURITY DEFINER over the owner-only owner_definer_read
--     policy (like app_capture_retention_targets in 0053); it returns a row only for an active
--     address, so an unknown, rotated and revoked address are all the same empty result.
--   * The #287 `email_intake` workspace_integration kind is replaced by the per-user address model:
--     its rows (a hash of a token nothing could receive mail with) are deleted and the kind check
--     narrows to ics_feed, so only one email scheme exists.
CREATE TABLE "intake_address" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"local_part" text NOT NULL,
	"domain" text NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"revoked_at" timestamp with time zone,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "intake_address_local_part_domain_uq" UNIQUE("local_part","domain"),
	CONSTRAINT "intake_address_status_chk" CHECK (status in ('active', 'revoked')),
	CONSTRAINT "intake_address_local_part_chk" CHECK (local_part ~ '^u-[a-z2-7]{10}$'),
	CONSTRAINT "intake_address_revoked_at_chk" CHECK ((status = 'revoked') = (revoked_at is not null))
);
--> statement-breakpoint
CREATE TABLE "intake_allowlist" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"pattern" text NOT NULL,
	"kind" text NOT NULL,
	"label" text,
	"added_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "intake_allowlist_workspace_pattern_uq" UNIQUE("workspace_id","pattern"),
	CONSTRAINT "intake_allowlist_kind_chk" CHECK (kind in ('court', 'efiling', 'self', 'briefing_counsel')),
	CONSTRAINT "intake_allowlist_pattern_chk" CHECK (pattern = lower(pattern) and length(pattern) <= 254)
);
--> statement-breakpoint
CREATE TABLE "intake_message" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"message_id" text NOT NULL,
	"status" text DEFAULT 'received' NOT NULL,
	"raw_mime_ref" text,
	"raw_expires_at" timestamp with time zone NOT NULL,
	"pinned" boolean DEFAULT false NOT NULL,
	"received_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "intake_message_workspace_message_id_uq" UNIQUE("workspace_id","message_id"),
	CONSTRAINT "intake_message_status_chk" CHECK (status in ('received', 'processed', 'quarantined', 'dropped'))
);
--> statement-breakpoint
