CREATE POLICY "owner_definer_read" ON "intake_address" AS PERMISSIVE FOR SELECT TO causedeck_owner
  USING (true);--> statement-breakpoint
CREATE FUNCTION app_resolve_intake_address(p_local_part text, p_domain text)
  RETURNS TABLE (workspace_id uuid, user_id uuid)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT a.workspace_id, a.user_id FROM intake_address a
    WHERE a.local_part = p_local_part AND a.domain = p_domain AND a.status = 'active'
    LIMIT 1
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_resolve_intake_address(text, text) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_resolve_intake_address(text, text) TO causedeck_app;
